BEGIN;
-- Product requested at PLN 150 net per microphone/day. No assumed employee or purchase costs.
DO $guard$ BEGIN
 IF EXISTS (SELECT 1 FROM public.offer_products WHERE lower(trim(name))='mikrofon nagłowny') THEN
  RAISE EXCEPTION 'Produkt Mikrofon nagłowny już istnieje. Przerwano, aby nie utworzyć duplikatu.';
 END IF;
END $guard$;
INSERT INTO public.offer_products (id,category_id,name,description,unit,min_quantity,is_active,base_price,price_net,price_gross,vat_rate,cost_price,cost_net,cost_gross,tags,offer_short_description,offer_compact_description,offer_description,public_description,offer_image_path,offer_image_alt,offer_image_position_x,offer_image_position_y,offer_image_zoom,offer_page_enabled,offer_page_variant,offer_benefits,offer_additional_requirements)
 SELECT id,category_id,name,description,unit,min_quantity,is_active,base_price,price_net,price_gross,vat_rate,cost_price,cost_net,cost_gross,tags,offer_short_description,offer_compact_description,offer_description,public_description,offer_image_path,offer_image_alt,offer_image_position_x,offer_image_position_y,offer_image_zoom,offer_page_enabled,offer_page_variant,offer_benefits,offer_additional_requirements FROM jsonb_populate_record(NULL::public.offer_products,'{"id": "5c0f045a-0212-46a7-b8aa-9b33be1be9f8", "category_id": "318deefd-b15e-40c4-aa08-78a7b9bad259", "name": "Mikrofon nagłowny", "description": "Wynajem mikrofonu nagłownego do prezentacji, szkoleń, prowadzenia wydarzeń i wystąpień scenicznych. Mikrofon jest noszony na głowie, dzięki czemu użytkownik może mówić bez trzymania mikrofonu w dłoni. Cena dotyczy 1 mikrofonu na 1 dzień. Model dobieramy do dostępności i zgodności z systemem audio. Nadajnik, odbiornik, nagłośnienie, obsługa i transport wymagają określenia w ofercie.", "unit": "szt. / dzień", "min_quantity": 1, "is_active": true, "base_price": 150, "price_net": 150, "price_gross": 184.5, "vat_rate": 23, "cost_price": null, "cost_net": null, "cost_gross": null, "tags": ["mikrofon nagłowny", "wynajem", "nagłośnienie"], "offer_short_description": "Mikrofon noszony na głowie do prezentacji, prowadzenia wydarzeń i wystąpień.", "offer_compact_description": "Wynajem 1 mikrofonu nagłownego na 1 dzień. Pozwala mówić z wolnymi rękami. Wymaga zgodnego nadajnika i toru nagłośnienia; ich zakres oraz obsługę ustalamy w ofercie.", "offer_description": "Wynajem mikrofonu nagłownego do prezentacji, szkoleń, prowadzenia wydarzeń i wystąpień scenicznych. Mikrofon jest noszony na głowie, dzięki czemu użytkownik może mówić bez trzymania mikrofonu w dłoni. Cena dotyczy 1 mikrofonu na 1 dzień. Model dobieramy do dostępności i zgodności z systemem audio. Nadajnik, odbiornik, nagłośnienie, obsługa i transport wymagają określenia w ofercie.", "public_description": "Mikrofon nagłowny — wynajem na dzień\n\nMikrofon noszony na głowie służy do przekazywania mowy podczas prezentacji, szkoleń, konferencji i prowadzenia wydarzeń. Pozostawia obie ręce wolne, np. do obsługi prezentacji lub pokazywania przedmiotów. Przed wystąpieniem należy dopasować ułożenie mikrofonu i wykonać próbę dźwięku.\n\nZakres i cena\nStawka wynosi 150 zł netto za 1 mikrofon na 1 dzień. Liczbę urządzeń, dni wynajmu oraz godziny przekazania i zwrotu ustalamy w ofercie. Przy kilku mikrofonach lub dniach cena jest liczona odpowiednio do zamówionego zakresu.\n\nDobór sprzętu\nModel dobieramy do dostępności i zgodności z używanym systemem. Zdjęcie przedstawia mikrofon Shure DH5 z naszego wyposażenia; konkretny model potwierdzamy przed realizacją.\n\nPodłączenie i przygotowanie\nSam mikrofon nagłowny nie jest kompletnym systemem nagłośnienia. Do pracy bezprzewodowej wymaga zgodnego nadajnika i odbiornika, a do nagłośnienia sali także odpowiedniego toru audio. Przed zamówieniem uzgadniamy zgodność złączy oraz urządzeń. Nadajnik, odbiornik, nagłośnienie, obsługa techniczna i transport nie są automatycznie objęte ceną samego mikrofonu — ich zakres i wycenę określa oferta.", "offer_image_path": "assets/5c0f045a-0212-46a7-b8aa-9b33be1be9f8/mikrofon-naglowny.webp", "offer_image_alt": "Mikrofon nagłowny Shure DH5 — zdjęcie sprzętu, model potwierdzany w ofercie", "offer_image_position_x": 50, "offer_image_position_y": 50, "offer_image_zoom": 0.8, "offer_page_enabled": true, "offer_page_variant": "default", "offer_benefits": ["Wolne ręce podczas wystąpienia", "Mikrofon noszony na głowie", "Rozliczenie za liczbę mikrofonów i dni wynajmu"], "offer_additional_requirements": [{"id": "8088752b-15d0-4087-ba3a-aa2113e6e6d1", "title": "ZGODNOŚĆ SYSTEMU AUDIO", "category": "resources", "description": "Przed realizacją potwierdzamy zgodny nadajnik, odbiornik i tor nagłośnienia."}, {"id": "548dcd01-cf44-4daa-b6b5-a724eae8f40a", "title": "PRÓBA DŹWIĘKU", "category": "setup", "description": "Zapewnij czas na dopasowanie mikrofonu i próbę dźwięku przed wystąpieniem."}]}'::jsonb)
 RETURNING id,name,price_net,price_gross,unit,offer_image_path;
COMMIT;
